const formatters = {
  plain: {
    format(order) {
      return `${order.id}: ${order.total}`;
    },
  },
};

function createFormatter(name) {
  return formatters[name];
}

export function labelOrder(order) {
  const formatter = createFormatter('plain');
  return formatter.format(order);
}

